style.css:
/* Dark background for reduced eye strain */
body {
    background-color: #121212;
    color: #e6e6e6;
}

/* Style text inputs and areas */
textarea, input {
    background-color: #333333;
    color: #e6e6e6;
    border: 1px solid #555555;
    font-size: 14px;
}


/* Style buttons for visibility */
button {
    background-color: #4CAF50;
    color: white;
    border: none;
}
